function horn(parent,s){const points=[];for(let i=0;i<=18;i++){const t=i/18;points.push(new THREE.Vector3(s*(2.5+t*2.5-t*t*.6),5.4+t*.2+t*t*3,-4+t*1.3));}const curve=new THREE.CatmullRomCurve3(points);const frames=curve.computeFrenetFrames(28,false),verts=[],idx=[];for(let j=0;j<=28;j++){const t=j/28,p=curve.getPointAt(t),rad=.65*Math.pow(1-t,.75)+.012;for(let k=0;k<10;k++){const a=k/10*Math.PI*2;const v=p.clone().addScaledVector(frames.normals[j],Math.cos(a)*rad).addScaledVector(frames.binormals[j],Math.sin(a)*rad);verts.push(v.x,v.y,v.z);if(j<28){const u=j*10+k,vv=j*10+(k+1)%10;idx.push(u,vv,u+10,vv,vv+10,u+10);}}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(idx);g.computeVertexNormals();mesh(g,ivory,0,0,0,parent);}
const bulls=[];function spawnBull(x,z,index=0){const root=new THREE.Group();scene.add(root);const sculpt=new THREE.Group();root.add(sculpt);const lobes=[];for(let i=0;i<65;i++){const a=rand(0,Math.PI*2),t=rand(-1,1),r=Math.sqrt(1-t*t);let o=mesh(new THREE.IcosahedronGeometry(1,1),cloudMat,Math.cos(a)*r*4.5,4+t*3.6,Math.sin(a)*r*4,sculpt);o.scale.set(rand(1,2),rand(.8,1.8),rand(1,2));o.rotation.set(rand(0,3),rand(0,3),rand(0,3));lobes.push(o);}const face=mesh(new THREE.IcosahedronGeometry(1,2),cloudMat,0,3.8,-3.6,sculpt);face.scale.set(2.9,2.6,2);mesh(new THREE.SphereGeometry(1,12,8),dark,0,2.8,-5,sculpt).scale.set(2,1.2,1);for(let s of [-1,1]){mesh(new THREE.SphereGeometry(.17,8,8),bullEye,s*1.6,4.5,-5.05,sculpt);let brow=box(cloudMat,s*1.6,4.9,-4.9,1.6,.5,.7,sculpt);brow.rotation.z=s*.27;horn(sculpt,s);}const swirl=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(.65,0),cloudMat,100);root.add(swirl);const lane=mesh(new THREE.PlaneGeometry(7,1),new THREE.MeshBasicMaterial({color:'#eec47d',transparent:true,opacity:.15,depthWrite:false}));lane.rotation.x=-Math.PI/2;lane.position.y=.06;root.position.set(x,0,z);const b={root,sculpt,lobes,swirl,lane,state:'seek',timer:1.5,index,dir:new THREE.Vector3(),start:new THREE.Vector3(),awarded:false,size:1};bulls.push(b);return b;}
spawnBull(0,-42);
const debrisCount=900,debris=new THREE.InstancedMesh(boxG,wood,debrisCount);debris.instanceMatrix.setUsage(THREE.DynamicDrawUsage);scene.add(debris);const debrisData=[];let debrisCursor=0;for(let i=0;i<debrisCount;i++){dummy.scale.setScalar(0);dummy.updateMatrix();debris.setMatrixAt(i,dummy.matrix);}function scatter(p,scale,color){const i=debrisCursor++%debrisCount;debrisData[i]={p:p.clone(),v:new THREE.Vector3(rand(-15,15),rand(10,22),rand(-15,15)),s:scale.clone(),life:rand(5,9),rot:new THREE.Vector3(rand(0,6),rand(0,6),rand(0,6))};debris.setColorAt(i,new THREE.Color(color));}
const bursts=[];function announce(t,sub=''){ $('#callout').textContent=t;$('#subcall').textContent=sub;clearTimeout(announce.timeout);announce.timeout=setTimeout(()=>{$('#callout').textContent='';$('#subcall').textContent='';},1800);}
let audio,master,wind;function initAudio(){if(audio){audio.resume();return;}audio=new AudioContext();master=audio.createGain();master.gain.value=.3;master.connect(audio.destination);const buf=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate);const d=buf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;wind=audio.createBufferSource();wind.buffer=buf;wind.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=350;const gain=audio.createGain();gain.gain.value=.12;wind.connect(filter).connect(gain).connect(master);wind.start();$('#sound').textContent='Sound ●';loadSfx('sfx_structure_break.ogg');startMusic();}
// Alia's score: rotate the delivered tracks, shuffled, with a crossfade; missing files are skipped.
const MUSIC=['music_prairie_loop.ogg',...Array.from({length:9},(_,i)=>'music_prairie_'+String(i+2).padStart(2,'0')+'.ogg')];let musicLevels={},musicBus,musicOrder=[],musicIdx=0,musicMissing=new Set();
function startMusic(){if(musicBus)return;musicBus=audio.createGain();musicBus.gain.value=.55;musicBus.connect(master);musicOrder=MUSIC.slice().sort(()=>Math.random()-.5);musicOrder.unshift(...musicOrder.splice(musicOrder.indexOf(MUSIC[0]),1));playNextTrack();}
// Tracks arrive at different loudness (prairie_09 is ~18 dB under the rest), so each one is levelled to a common RMS, peak-limited.
function trackLevel(buf){let sum=0,peak=0,n=0;for(let c=0;c<buf.numberOfChannels;c++){const d=buf.getChannelData(c);for(let i=0;i<d.length;i+=16){const v=Math.abs(d[i]);sum+=v*v;if(v>peak)peak=v;n++;}}const rms=Math.sqrt(sum/Math.max(1,n));return rms>1e-4?clamp(.2/rms,.4,Math.min(6,.9/Math.max(peak,1e-3))):1;}
async function playNextTrack(tries=0){if(tries>=MUSIC.length)return;const name=musicOrder[musicIdx++%musicOrder.length];if(musicMissing.has(name))return playNextTrack(tries+1);let buf;try{const r=await fetch('../assets/'+name);if(!r.ok)throw 0;buf=await audio.decodeAudioData(await r.arrayBuffer());}catch{musicMissing.add(name);return playNextTrack(tries+1);}const src=audio.createBufferSource();src.buffer=buf;const g=audio.createGain();const t0=audio.currentTime,fade=3;const level=trackLevel(buf);musicLevels[name]=level;g.gain.setValueAtTime(0,t0);g.gain.linearRampToValueAtTime(level,t0+fade);src.connect(g).connect(musicBus);src.start(t0);setTimeout(()=>playNextTrack(),Math.max(1,(buf.duration-fade)*1000));}
// Alia's sfx (StormDodger-1542e36e-006 structure break); the synthesized tone stays as fallback.
const SFX={};let lastBreak=-1;function loadSfx(name){if(name in SFX)return;SFX[name]=null;fetch('../assets/'+name).then(r=>{if(!r.ok)throw 0;return r.arrayBuffer();}).then(b=>audio.decodeAudioData(b)).then(buf=>SFX[name]=buf).catch(()=>SFX[name]=false);}
function playSfx(name,vol=1){const buf=audio&&SFX[name];if(!buf)return false;const src=audio.createBufferSource(),g=audio.createGain();src.buffer=buf;g.gain.value=vol;src.connect(g).connect(master);src.start();return true;}
function tone(f,d=.25,v=.3,type='sine'){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,f*.2),audio.currentTime+d);g.gain.setValueAtTime(v,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(master);o.start();o.stop(audio.currentTime+d);}
function save(){localStorage.setItem('stormDodger1542',JSON.stringify({bank,levels}));}
function reward(n){n=Math.round(n*(1+levels[3]*.35)*combo);if(quick)quickScore+=n;else bank+=n;$('#score').textContent=Math.floor(quick?quickScore:bank).toLocaleString();save();return n;}
function destroy(b){if(b.dead)return;b.dead=true;b.rebuildAt=elapsed+80;destroyed++;if(b.model)b.model.visible=false;for(const c of b.chunks){const p=c.getWorldPosition(new THREE.Vector3());scatter(p,c.scale,c.material.color);showPart(c,false);}shake=Math.max(shake,.45);if(!audio||audio.currentTime-lastBreak>.07){if(audio)lastBreak=audio.currentTime;if(!playSfx('sfx_structure_break.ogg',b.type===-1?.45:1.1))tone(65,.6,.6,'sawtooth');}const n=reward(b.type===-1?35:240);if(b.type!==-1)announce('+'+n.toLocaleString(),'FRONTIER / UNDONE');}
function dodge(){if(cooldown>0||!$('#shop').hidden||!$('#end').hidden)return;initAudio();if(firstAction===null)firstAction=elapsed;dodges++;dodgeT=.48;cooldown=Math.max(.45,1.15-levels[0]*.08);invuln=.65;dodgeDir.copy(velocity.lengthSq()>.1?velocity:new THREE.Vector3(Math.cos(yaw),0,-Math.sin(yaw))).normalize();tone(260,.18,.16,'triangle');shake=.12;}
function taunt(){initAudio();tauntT=1.2;for(const b of bulls)if(b.state==='seek'){b.timer=.3;}tone(650,.3,.15,'triangle');announce('COME ON.','⚑');}
const branches=[['Boots','Longer dives. Slide. Air step.'],['Cape','Wider lure. Golden storm ribbons.'],['Nerve','Perfect timing. Recover your grit.'],['Fortune','Bigger banks. Longer style chains.'],['Weather','Twins. Embers. Hail. Storm king.'],['Rider','Launch. Glide. Mount the storm.']];function cost(i){return Math.round(300*Math.pow(1.75,levels[i]));}
function renderShop(){ $('#upgrades').innerHTML=branches.map(([n,d],i)=>`<article class="upgrade"><h3>${n} <small>${levels[i]}/8</small></h3><p>${d}</p><div class="tier">${'◆'.repeat(levels[i])}${'◇'.repeat(8-levels[i])}</div><button data-buy="${i}">${levels[i]===8?'Mastered':cost(i).toLocaleString()+' Olé ↗'}</button></article>`).join('');document.querySelectorAll('[data-buy]').forEach(el=>el.onclick=()=>buy(+el.dataset.buy));}
function buy(i){if(quick){announce('FREE ROAM ONLY');return false;}if(levels[i]>=8||bank<cost(i)){tone(90,.15);return false;}bank-=cost(i);levels[i]++;health=3;save();renderShop();announce(branches[i][0].toUpperCase()+' ↑','TIER '+levels[i]);tone(750,.4);return true;}
function shop(){ $('#shop').hidden=!$('#shop').hidden;if(!$('#shop').hidden)renderShop();}
function reset(mode){quick=mode;session=0;quickScore=0;combo=1;health=3;player.position.set(0,0,0);mounted=false;$('#end').hidden=true;$('#shop').hidden=true;$('#main').classList.toggle('active',!quick);$('#quick').classList.toggle('active',quick);for(const b of bulls){b.root.position.set(b.index*25,0,-42-b.index*20);b.state='seek';b.timer=1.5;}for(const b of buildings){b.dead=false;setIntact(b);}announce(quick?'ONE CHARGE':'HOLD YOUR GROUND','DODGE / REDIRECT / DESTROY');}
$('#main').onclick=()=>reset(false);$('#quick').onclick=()=>reset(true);$('#again').onclick=()=>reset(true);$('#shopButton').onclick=shop;$('#close').onclick=shop;$('#sound').onclick=()=>{initAudio();master.gain.value=master.gain.value?0:.3;$('#sound').textContent=master.gain.value?'Sound ●':'Sound ○';};$('#touchDodge').onpointerdown=dodge;$('#touchTaunt').onpointerdown=taunt;
function ride(){if(levels[5]<2){announce('RIDER II / GLIDE','UPGRADE AT THE WORKSHOP');return;}if(levels[5]>=5){mounted=!mounted;announce(mounted?'STORM RIDER':'RELEASED');}else{player.position.y=10;invuln=2;tone(180,.4);}}
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','Tab','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space')dodge();if(e.code==='KeyE')taunt();if(e.code==='Tab')shop();if(e.code==='KeyQ')ride();});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
$('#world').addEventListener('pointerdown',e=>{initAudio();drag=true;mouseX=e.clientX;});addEventListener('pointerup',()=>drag=false);addEventListener('pointermove',e=>{if(drag){yaw-=(e.clientX-mouseX)*.005;mouseX=e.clientX;}});
let touchStart=null;$('#world').addEventListener('touchstart',e=>{touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});$('#world').addEventListener('touchmove',e=>{if(!touchStart)return;const t=e.touches[0];keys.KeyW=t.clientY<touchStart.y-15;keys.KeyS=t.clientY>touchStart.y+15;keys.KeyA=t.clientX<touchStart.x-15;keys.KeyD=t.clientX>touchStart.x+15;},{passive:true});$('#world').addEventListener('touchend',()=>{touchStart=null;['KeyW','KeyS','KeyA','KeyD'].forEach(k=>keys[k]=false);});
let quality='medium';function setQuality(q){quality=q;renderer.setPixelRatio(Math.min(devicePixelRatio,q==='low'?1:q==='medium'?1.5:2));renderer.shadowMap.enabled=q!=='low';grass.count=q==='low'?3500:q==='medium'?8000:13000;$('#quality').value=q;}setQuality(navigator.hardwareConcurrency<=4?'low':'medium');$('#quality').onchange=e=>setQuality(e.target.value);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
let fps=60,frames=0,ft=0;function step(dt){elapsed+=dt;session+=dt;cooldown=Math.max(0,cooldown-dt);invuln=Math.max(0,invuln-dt);tauntT=Math.max(0,tauntT-dt);dodgeT=Math.max(0,dodgeT-dt);slow=Math.max(0,slow-dt);shake*=Math.pow(.025,dt);const paused=!$('#shop').hidden||!$('#end').hidden;const gameDt=paused?0:dt*(slow>0?.22:1);
const pad=navigator.getGamepads?.()[0];if(pad){keys.KeyW=pad.axes[1]<-.2;keys.KeyS=pad.axes[1]>.2;keys.KeyA=pad.axes[0]<-.2;keys.KeyD=pad.axes[0]>.2;if(pad.buttons[0].pressed)dodge();if(pad.buttons[2].pressed&&tauntT<=0)taunt();yaw-=pad.axes[2]*dt*2;}
let mx=(keys.KeyD?1:0)-(keys.KeyA?1:0),mz=(keys.KeyS?1:0)-(keys.KeyW?1:0);velocity.set(mx,0,mz).normalize().applyAxisAngle(new THREE.Vector3(0,1,0),yaw);if(!paused){if(velocity.lengthSq()&&firstAction===null)firstAction=elapsed;player.position.addScaledVector(dodgeT>0?dodgeDir:velocity,gameDt*(dodgeT>0?24+levels[0]*2:9+levels[0]*.45));if(velocity.lengthSq())player.rotation.y=Math.atan2(velocity.x,velocity.z);player.position.x=clamp(player.position.x,-280,280);player.position.z=clamp(player.position.z,-300,160);player.position.y=Math.max(0,player.position.y-gameDt*(levels[5]>=2?3:15));}player.rotation.z=dodgeT>0?Math.sin(dodgeT*8)*.65:0;torso.rotation.x=dodgeT>0?-.6:0;if(matadorPivot){matadorPivot.rotation.x=dodgeT>0?.35:0;matadorPivot.position.y=dodgeT<=0&&velocity.lengthSq()?Math.abs(Math.sin(elapsed*9))*.12:0;}legs.forEach((l,i)=>l.rotation.x=Math.sin(elapsed*13+i*Math.PI)*.55*(velocity.lengthSq()||dodgeT>0?1:0));const cp=cape.geometry.attributes.position;for(let i=0;i<cp.count;i++){cp.setZ(i,Math.sin(elapsed*9+cp.getY(i)*3)*.17*(1+tauntT*3));}cp.needsUpdate=true;cape.scale.set(1+levels[1]*.1,1+levels[1]*.05,1);cape.material.color.setHSL(.015+levels[1]*.009,.65,.32+levels[1]*.02);
for(const h of buildings)if(h.dead&&elapsed>h.rebuildAt&&Math.hypot(h.x-player.position.x,h.z-player.position.z)>40){h.dead=false;setIntact(h);}
const targetCount=1+(levels[4]>=2?1:0)+(levels[4]>=6?1:0)+(quick&&session>50?1:0);while(bulls.length<targetCount)spawnBull(rand(-35,35),-60,bulls.length);
for(const b of bulls){b.size=1.35+levels[4]*.11+(quick?session*.003:0);b.sculpt.scale.setScalar(b.size);const bp=b.root.position;const dist=bp.distanceTo(player.position);b.timer-=gameDt;const targetAngle=Math.atan2(player.position.x-bp.x,player.position.z-bp.z)+Math.PI;
if(mounted&&b.index===0){b.state='ridden';bp.copy(player.position);bp.y=0;player.position.y=9*b.size;bp.addScaledVector(velocity,gameDt*18);player.position.x=bp.x;player.position.z=bp.z;b.root.rotation.y=player.rotation.y+Math.PI;for(const h of buildings)if(!h.dead&&Math.hypot(h.x-bp.x,h.z-bp.z)<11*b.size)destroy(h);}
else if(b.state==='ridden'){b.state='seek';b.timer=2;}
else if(b.state==='seek'){b.lane.visible=false;b.root.rotation.y=targetAngle;if(dist>32)bp.addScaledVector(player.position.clone().sub(bp).setY(0).normalize(),gameDt*6);if(b.timer<=0&&dist<70+levels[1]*6){b.state='warn';b.timer=1.5;b.dir.copy(player.position).sub(bp).setY(0).normalize();b.start.copy(bp);b.awarded=false;tone(48,1,.22,'sawtooth');}}
else if(b.state==='warn'){b.dir.copy(player.position).sub(bp).setY(0).normalize();b.root.rotation.y=targetAngle;b.sculpt.rotation.x=-.12;b.lane.visible=true;const len=Math.max(30,dist+30);b.lane.scale.set(1,len,1);b.lane.position.copy(bp).addScaledVector(b.dir,len/2);b.lane.position.y=.08;b.lane.rotation.z=-Math.atan2(b.dir.x,b.dir.z);b.lane.material.opacity=.12+Math.sin(elapsed*18)*.08;$('#hint').textContent=dist<55?'Wait for the horns…':'Bring the storm closer.';if(b.timer<=0){b.state='charge';b.timer=2.4;b.root.rotation.y=Math.atan2(-b.dir.x,-b.dir.z);tone(45,.7,.5,'sawtooth');}}
else if(b.state==='charge'){b.lane.visible=false;bp.addScaledVector(b.dir,gameDt*(31+levels[4]*2+(quick?session*.035:0)));b.sculpt.rotation.x=.08;const delta=player.position.clone().sub(bp),along=delta.dot(b.dir),side=Math.abs(delta.x*b.dir.z-delta.z*b.dir.x);if(!b.awarded&&Math.abs(along)<7*b.size&&side<15*b.size){if(dodgeT>0||invuln>0){b.awarded=true;const perfect=side<6+levels[2]*.5;combo=Math.min(20,combo+(perfect?1:.25));perfects+=perfect?1:0;const n=reward(perfect?180:80);announce(perfect?'¡OLÉ! +'+n:'CLOSE! +'+n,perfect?'PERFECT / KEEP DANCING':'DODGE / KEEP MOVING');slow=perfect?.32:0;shake=.3;tone(perfect?880:500,.3,.25,'triangle');if(perfect&&levels[2]>=3)health=Math.min(3,health+1);}else if(side<4.3*b.size&&Math.abs(along)<4*b.size){b.awarded=true;health--;invuln=2;combo=1;shake=.8;tone(75,.4,.6,'square');announce('GET UP.','THE PRAIRIE IS YOURS');player.position.addScaledVector(new THREE.Vector3(b.dir.z,0,-b.dir.x),6);if(health<=0){health=3;if(quick){finish();}else{bank=Math.max(0,bank-100);save();}}}}
for(const h of buildings)if(!h.dead&&Math.hypot(h.x-bp.x,h.z-bp.z)<h.radius+5*b.size)destroy(h);if(b.timer<=0||Math.abs(bp.x)>320||Math.abs(bp.z)>350){b.state='rest';b.timer=2;}}
else if(b.state==='rest'){b.sculpt.rotation.x=0;if(b.timer<=0){b.state='seek';b.timer=2;}}
b.lobes.forEach((o,i)=>{o.rotation.y+=gameDt*(i%2?.07:-.09);o.position.y+=Math.sin(elapsed*2+i)*.002;});for(let i=0;i<100;i++){const t=i/100,a=elapsed*(1.8+t)+i*2.4,r=(2+t*5)*b.size;dummy.position.set(Math.cos(a)*r,t*12,Math.sin(a)*r);dummy.rotation.set(a,a*.6,0);dummy.scale.setScalar((.3+Math.sin(i)*.15)*(1-t*.6));dummy.updateMatrix();b.swirl.setMatrixAt(i,dummy.matrix);}b.swirl.instanceMatrix.needsUpdate=true;}
for(let i=0;i<debrisData.length;i++){const d=debrisData[i];if(!d||d.life<=0)continue;d.life-=gameDt;const nearest=bulls.find(b=>b.root.position.distanceTo(d.p)<20);if(nearest&&d.life>2){const dx=d.p.x-nearest.root.position.x,dz=d.p.z-nearest.root.position.z;d.v.x+=(-dz*.8-dx*.1)*gameDt;d.v.z+=(dx*.8-dz*.1)*gameDt;d.v.y+=8*gameDt;}d.v.y-=12*gameDt;d.p.addScaledVector(d.v,gameDt);if(d.p.y<.2){d.p.y=.2;d.v.y*=-.25;d.v.x*=.95;d.v.z*=.95;}d.rot.x+=gameDt;d.rot.y+=gameDt*2;dummy.position.copy(d.p);dummy.rotation.set(d.rot.x,d.rot.y,d.rot.z);dummy.scale.copy(d.s).multiplyScalar(Math.min(1,d.life));dummy.updateMatrix();debris.setMatrixAt(i,dummy.matrix);}debris.instanceMatrix.needsUpdate=true;if(debris.instanceColor)debris.instanceColor.needsUpdate=true;
const desired=new THREE.Vector3(Math.sin(yaw)*24,8+camPitch*8,Math.cos(yaw)*24).add(player.position);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.position.x+=rand(-shake,shake);camera.position.y+=rand(-shake,shake);camera.lookAt(player.position.x,player.position.y+4,player.position.z-7);sun.position.set(player.position.x+110,75,player.position.z-110);sun.target.position.copy(player.position);scene.add(sun.target);
let near=regions.reduce((a,r)=>Math.hypot(r[1]-player.position.x,r[2]-player.position.z)<Math.hypot(a[1]-player.position.x,a[2]-player.position.z)?r:a,regions[0]);$('#region').textContent='0'+(regions.indexOf(near)+1)+' / '+near[0];$('#score').textContent=Math.floor(quick?quickScore:bank).toLocaleString();$('#combo').textContent='×'+combo.toFixed(1)+' STYLE';$('#timer').textContent=quick?Math.max(0,120-Math.floor(session))+'s LEFT':'∞ ROAM';document.querySelectorAll('#health i').forEach((e,i)=>e.style.opacity=i<health?1:.2);if(quick&&session>=120&&$('#end').hidden)finish();}
function finish(){$('#end').hidden=false;$('#endScore').textContent=quickScore.toLocaleString()+' Olé';}
function frame(){requestAnimationFrame(frame);const raw=clock.getDelta();let dt=Math.min(raw,.15);step(dt);renderer.render(scene,camera);frames++;ft+=raw;if(ft>=1){fps=frames/ft;frames=0;ft=0;}}camera.position.set(0,14,27);announce('HOLD YOUR GROUND','SPACE / DODGE');frame();

